const rows = $("Memória: lê histórico").all().map(i => i.json);
const ordered = rows.slice().reverse();
const historico = ordered.map(r => (r.role === 'user' ? 'Lead: ' : 'Assistente: ') + (r.conteudo || '')).join('\n');
const texto = $("Redis: lê texto completo").first().json.textoCompleto || $("Monta buffer").first().json.bufNovo || '';
const leadNome = $("Valida lead + Z-API remetente").first().json.lead_nome || '';
const vendedor = $("Valida lead + Z-API remetente").first().json.vendedor_nome || '';
const promptUsuario = `Dados do lead: nome=${leadNome}; vendedor responsável=${vendedor}.\n\nHistórico da conversa:\n${historico || '(sem histórico ainda)'}\n\nNova mensagem do lead:\n${texto}`;
return [{ json: { promptUsuario } }];

const j = $input.first().json;

// Com JSON Schema, a resposta vem como OBJETO aqui:
let node = j.output?.[0]?.content?.[0]?.text
        ?? j.message?.content
        ?? j.choices?.[0]?.message?.content
        ?? j.content ?? j.text ?? j;

let parsed;
if (node && typeof node === 'object') {
  parsed = node;                       // já é objeto, usa direto
} else {
  const s = String(node ?? '');
  try { parsed = JSON.parse(s); }
  catch (e) { const m = s.match(/\{[\s\S]*\}/); parsed = m ? JSON.parse(m[0]) : {}; }
}

return [{ json: {
  responder: !!parsed.responder,
  mensagem: parsed.mensagem || '',
  encerrar: !!parsed.encerrar,
  classificacao: parsed.classificacao || 'outro',
  resumo: parsed.resumo || '',
  notificar_vendedor: !!parsed.notificar_vendedor,
  notificar_gestor: !!parsed.notificar_gestor,
  motivo_gestor: parsed.motivo_gestor || ''
} }];

