parameters.jsCode:
const msg = ($('Interpreta resposta da IA').item.json.mensagem || '').trim();
const LIMITE = 350;
let partes = [];
if (msg.length <= LIMITE) { partes = [msg]; }
else {
  const blocos = msg.split(/\n+/);
  let atual = '';
  for (const b of blocos) {
    if ((atual + '\n' + b).length > LIMITE && atual) { partes.push(atual.trim()); atual = b; }
    else { atual = atual ? atual + '\n' + b : b; }
  }
  if (atual) partes.push(atual.trim());
  if (partes.length > 2) partes = [partes[0], partes.slice(1).join('\n')];
}
return partes.filter(p => p.length).map((p, idx) => ({ json: { parte: p, indice: idx } }));

textOptions.schema:
{
  "type": "object",
  "properties": {
    "responder": {
      "type": "boolean",
      "description": "true se convém enviar uma resposta ao lead; false quando não vale responder (ex.: agradecimento repetido ou conversa já encerrada)."
    },
    "mensagem": {
      "type": "string",
      "description": "Texto da resposta a enviar ao lead. Vazio quando responder=false."
    },
    "encerrar": {
      "type": "boolean",
      "description": "true quando a conversa chegou a um fim natural."
    },
    "classificacao": {
      "type": "string",
      "enum": ["preco", "duvida", "interesse", "agendamento", "reclamacao", "sem_interesse", "outro"],
      "description": "Categoria principal da mensagem do lead."
    },
    "resumo": {
      "type": "string",
      "description": "Uma frase curta do que o lead quer/precisa, para avisar o vendedor."
    },
    "notificar_vendedor": {
      "type": "boolean",
      "description": "true quando há algo acionável para o vendedor (preço, dúvida, interesse, agendamento, reclamação)."
    },
    "notificar_gestor": {
      "type": "boolean",
      "description": "true apenas em reclamação: apresentação ruim, problema com o vendedor, ou vendedor não retornou."
    },
    "motivo_gestor": {
      "type": "string",
      "description": "Uma frase descrevendo o problema quando notificar_gestor=true; vazio caso contrário."
    }
  },
  "required": ["responder", "mensagem", "encerrar", "classificacao", "resumo", "notificar_vendedor", "notificar_gestor", "motivo_gestor"],
  "additionalProperties": false
}

parameters.jsCode:
const b = $input.first().json.body || {};
if (b.event !== 'message') return [];  

const p = b.payload || {};
const info = (p._data && p._data.Info) || {};

// telefone real (SenderAlt); "from" é @lid e não serve
const alt = info.SenderAlt || info.Sender || p.from || '';
const telefone = String(alt).replace(/[:@].*$/, '');

const isGroup = !!info.IsGroup;
const chatId  = info.Chat || p.from || '';
const tipo    = (info.MediaType || info.Type || 'text').toLowerCase();

// media.url vem como localhost interno → troca pelo host público do WAHA (e baixamos com a API key)
const WAHA = 'http://waha.internal.local';
let mediaUrl = (p.media && p.media.url) || '';
mediaUrl = mediaUrl.replace('http://localhost:3000', WAHA);

const body = {
  phone: isGroup ? chatId : telefone,
  chatId: chatId,                         // <<< NOVO: o id do chat que recebeu (p/ responder)
  isGroup,
  participantPhone: telefone,
  senderName: info.PushName || '',
  fromMe: !!p.fromMe,
  type: 'ReceivedCallback',
  isStatusReply: false,
  messageId: p.id || info.ID || '',
  quotedId: (p.replyTo && p.replyTo.id) || ''
};

if (tipo === 'image') body.image = { imageUrl: mediaUrl };
else if (tipo === 'ptt' || tipo === 'audio') body.audio = { audioUrl: mediaUrl };
else body.text = { message: p.body || '' };

return [{ json: { event: b.event, session: b.session, body } }];

